contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry used by the verifier; takes parameters to drive supplyTokenTo
    function run(uint256 mAssetAmount, address to) public payable {
        require(to != address(0), "to non-zero");
        // Ensure this contract has enough mAsset tokens to transfer to c: we cannot mint tokens here.
        // We only observe behavior when transferFrom is attempted; if transferFrom would fail the call should revert.

        // Read pre-state: imBalances(to) and mAsset balance of c and this
        uint256 beforeIm = c.imBalances(to);
        address mAssetAddr = c.depositToken();
        IERC20 m = IERC20(mAssetAddr);
        uint256 cBalBefore = m.balanceOf(address(c));
        uint256 thisBalBefore = m.balanceOf(address(this));

        // Attempt the mutating call and record whether it reverted
        bool reverted;
        try c.supplyTokenTo(mAssetAmount, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-state
        uint256 afterIm = c.imBalances(to);
        uint256 cBalAfter = m.balanceOf(address(c));
        uint256 thisBalAfter = m.balanceOf(address(this));

        // If the call did not revert, then (1) c's mAsset balance must have increased by at least the amount taken from caller
        // and (2) imBalances[to] must be >= beforeIm (credits issued are non-negative) and the net increase equals the credits issued
        // We cannot call into savings to know exact creditsIssued, but we can assert consistency: imBalances increased iff c's balance increased.

        // Formulate general rule:
        // If not reverted: afterIm >= beforeIm, cBalAfter >= cBalBefore, and either both increases are zero or both increases are positive.
        // Also this contract's mAsset balance must not increase as a result (tokens moved from caller to c), so thisBalAfter <= thisBalBefore.

        assert(
            reverted
            || (
                afterIm >= beforeIm
                && cBalAfter >= cBalBefore
                && ((afterIm > beforeIm) == (cBalAfter > cBalBefore))
                && thisBalAfter <= thisBalBefore
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry used by the verifier; takes parameters to drive redeemToken
    function run(uint256 mAssetAmount) public payable {
        // No precondition on mAssetAmount; 0 is allowed.

        // Observe token address and balances before the call
        address mAssetAddr = c.depositToken();
        IERC20 m = IERC20(mAssetAddr);
        uint256 cBalBefore = m.balanceOf(address(c));
        uint256 callerImBefore = c.imBalances(address(this));

        // Attempt the mutating call and record whether it reverted
        bool reverted;
        uint256 mAssetsReturned;
        try c.redeemToken(mAssetAmount) returns (uint256 ret) {
            reverted = false;
            mAssetsReturned = ret;
        } catch {
            reverted = true;
            mAssetsReturned = 0;
        }

        // Observe balances after
        uint256 cBalAfter = m.balanceOf(address(c));
        uint256 callerImAfter = c.imBalances(address(this));
        uint256 thisBalAfter = m.balanceOf(address(this));

        // If call succeeded: (1) caller's imBalances must not increase, (2) c's mAsset balance must not increase,
        // (3) the actual tokens received by caller equals the reported return value, i.e., this contract's mAsset balance increased by mAssetsReturned,
        // (4) imBalances decreased by some non-negative amount (creditsBurned) and c's token balance decreased by at least that many underlying mAssets (consistency),
        // We cannot read creditsBurned directly, but we can assert that if imBalances decreased then c's token balance also decreased and vice versa.

        assert(
            reverted
            || (
                // caller's imBalances did not increase
                callerImAfter <= callerImBefore
                // c's token balance did not increase
                && cBalAfter <= cBalBefore
                // tokens received by caller equal the returned amount
                && thisBalAfter - /* safe since non-decreasing expected */ (thisBalAfter >= 0 ? 0 : 0) == mAssetsReturned
                // consistency between imBalances decrease and c token decrease: both decrease together or both unchanged
                && ((callerImBefore > callerImAfter) == (cBalBefore > cBalAfter))
            )
        );
    }

    receive() external payable {}
}

