        uint256 callerImBefore = c.imBalances(address(this));
        uint256 thisBalBefore = m.balanceOf(address(this));

        // Make the mutating call at top-level and capture revert or return
        bool reverted;
        uint256 returned;
        try c.redeemToken(mAssetAmount) returns (uint256 ret) {
            reverted = false;
            returned = ret;
        } catch {
            reverted = true;
            returned = 0;
        }

        // Observe after-state (view calls only)
        uint256 cBalAfter = m.balanceOf(address(c));
        uint256 callerImAfter = c.imBalances(address(this));
        uint256 thisBalAfter = m.balanceOf(address(this));

        // General rule: either the call reverted, or if it succeeded then
        // 1) the actual tokens received by this contract equals the returned value,
        // 2) the caller's imBalances did not increase,
        // 3) the contract's mAsset balance did not increase.
        assert(
            reverted || (
                // tokens received equals returned value
                thisBalAfter >= thisBalBefore && (thisBalAfter - thisBalBefore) == returned
                // caller's imBalances did not increase
                && callerImAfter <= callerImBefore
                // contract's mAsset balance did not increase
                && cBalAfter <= cBalBefore
            )
        );
    }

    receive() external payable {}
}

