contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test entry
    function run(address to, uint256 mAssetAmount) public payable {
        require(to != address(0));
        // Observe exchange rate and recipient balance before
        uint256 rateBefore = c.savings().exchangeRate();
        uint256 balBefore = c.balanceOfToken(to);

        // Try to perform a supply; record whether it reverted
        bool supplyReverted;
        try c.supplyTokenTo(mAssetAmount, to) {
            supplyReverted = false;
        } catch {
            supplyReverted = true;
        }

        // Observe after-values
        uint256 rateAfter = c.savings().exchangeRate();
        uint256 balAfter = c.balanceOfToken(to);

        // If supply succeeded, then the reported token-balance (in mAssets) for `to` must be >= prior + (mAssetAmount * exchangeRateAfter)/1e18
        // If supply reverted, balances must be unchanged.
        assert(
            supplyReverted
                ? (balAfter == balBefore)
                : (balAfter >= balBefore + (mAssetAmount * rateAfter) / 1e18)
        );
    }

    receive() external payable {}
}

