        uint256 callerUnderlyingAfter = c.balanceOfToken(address(this));

        // If redeem succeeded then:
        // - the contract's mAsset balance must have decreased by exactly redeemedActual
        // - the caller's balanceOfToken must not have increased (should decrease or stay same)
        // (We assert that on success contract balance delta equals redeemedActual and callerUnderlyingAfter <= callerUnderlyingBefore)
        assert(
            redeemedReverted
                ? (contractBalAfter == contractBalBefore) // if reverted, contract balance unchanged
                : (contractBalBefore >= contractBalAfter && (contractBalBefore - contractBalAfter) == redeemedActual && callerUnderlyingAfter <= callerUnderlyingBefore)
        );
