contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: tries supplyTokenTo and checks that if the call succeeds,
    // the reported balanceOfToken(to) (which returns mAssets computed from imBalances*exchangeRate/1e18)
    // does not decrease for `to` compared to before the call.
    function run(address from, address to, uint256 mAssetAmount) public payable {
        require(from != address(0) && to != address(0), "nonzero addrs");

        // Observe balanceOfToken(to) before the call
        uint256 before = c.balanceOfToken(to);

        // Perform the supply operation as the InvMutTest contract (msg.sender for c calls will be this contract).
        bool reverted;
        try c.supplyTokenTo(mAssetAmount, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after
        uint256 after = c.balanceOfToken(to);

        // General rule: if the call did not revert, the after-observed mAsset-equivalent balance must be >= before.
        // (i.e., supplying cannot decrease the beneficiary's token-equivalent balance)
        assert(reverted || after >= before);
    }

    receive() external payable {}
}

