contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will call redeemToken with a requested amount and check observable effects.
    // params: requested mAssetAmount to redeem, and an address 'toCheck' whose imBalances we will observe via balanceOfToken
    function run(uint256 requestedAmount, address toCheck) public payable {
        require(toCheck != address(0));

        // Snapshot observable values before the call
        uint256 beforeContractBalance = address(c).balance;
        // balanceOfToken uses savings.exchangeRate and imBalances[toCheck]; it's public view
        uint256 beforeBalanceOfToken = c.balanceOfToken(toCheck);

        bool reverted;
        uint256 returnedActual;
        // call redeemToken and catch revert
        try c.redeemToken(requestedAmount) returns (uint256 mAssetsActual) {
            reverted = false;
            returnedActual = mAssetsActual;
        } catch {
            reverted = true;
            returnedActual = 0;
        }

        // Snapshot after
        uint256 afterContractBalance = address(c).balance;
        uint256 afterBalanceOfToken = c.balanceOfToken(toCheck);

        // General rule (single assert):
        // If redeemToken did not revert, then the contract's mAsset (ERC20) balance increase for the test contract
        // is equal to returnedActual, and the observed balanceOfToken for any address (toCheck) did not increase.
        // If redeem reverted, no guarantees about returnedActual, but we still assert that afterBalanceOfToken >= 0 (always true)
        // The meaningful part is enforced when not reverted.
        assert(
            reverted || (
                // contract's ether balance change equals 0 because redeemToken doesn't transfer Ether; but since we cannot rely on internals,
                // we at least assert that the contract's ETH balance did not decrease when redeem succeeded
                afterContractBalance >= beforeContractBalance
                // and the returnedActual equals the increase in this contract's ERC20 mAsset balance as observed by the public c.redeemToken return
                // We cannot read c's internal ERC20 balances directly, but redeemToken returns mAssetsActual which must be non-negative
                && returnedActual >= 0
                // ensure that observed balanceOfToken for 'toCheck' did not increase (redeem reduces caller's imBalances; it should not increase others')
                && afterBalanceOfToken <= beforeBalanceOfToken
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry: try redeemToken and assert a general invariant about its observable effects.
    // Parameter: requested mAssetAmount to redeem, and an address toObserve whose balanceOfToken we read.
    function run(uint256 requestedAmount, address toObserve) public payable {
        require(toObserve != address(0));

        // Observe before-values
        uint256 beforeContractEth = address(c).balance;
        uint256 beforeBalanceOfToken = c.balanceOfToken(toObserve);

        bool reverted;
        uint256 returnedActual;
        // Call redeemToken and capture revert or return value
        try c.redeemToken(requestedAmount) returns (uint256 mAssetsActual) {
            reverted = false;
            returnedActual = mAssetsActual;
        } catch {
            reverted = true;
            returnedActual = 0;
        }

        // Observe after-values
        uint256 afterContractEth = address(c).balance;
        uint256 afterBalanceOfToken = c.balanceOfToken(toObserve);

        // Assert the general rule in one expression:
        // If the call reverted, we make no further claims. If it succeeded, then:
        // 1) returnedActual is >= 0 (always true for uint) and when returnedActual > 0 then the observed balanceOfToken for the caller (toObserve)
        //    did not increase (i.e., afterBalanceOfToken <= beforeBalanceOfToken). This captures that redeem burns/uses credits, not increases them.
        // 2) The contract's ETH balance did not decrease (redeemToken should not drain ETH).
        assert(
            reverted || (
                // returnedActual is uint so >= 0; require a meaningful connection: if returnedActual > 0 then observed balanceOfToken did not increase
                (returnedActual == 0 || afterBalanceOfToken <= beforeBalanceOfToken)
                && afterContractEth >= beforeContractEth
            )
        );
    }

    // No special receive logic required
    receive() external payable {}
}

