    function run(uint256 requestedAmount, address toObserve) public payable {
        require(toObserve != address(0));

        // Observe before-values: c's mAsset token balance and the observed address's balanceOfToken
        // We can observe c.mAsset balance via IERC20 public getter mAsset() then balanceOf
        IERC20 m = IERC20(c.depositToken());
        uint256 beforeContractMAsset = m.balanceOf(address(c));
        uint256 beforeBalanceOfToken = c.balanceOfToken(toObserve);

        bool reverted;
        uint256 returnedActual;
        // Call redeemToken and capture revert or return value
        try c.redeemToken(requestedAmount) returns (uint256 mAssetsActual) {
            reverted = false;
            returnedActual = mAssetsActual;
        } catch {
            reverted = true;
            returnedActual = 0;
        }

        // Observe after-values
        uint256 afterContractMAsset = m.balanceOf(address(c));
        uint256 afterBalanceOfToken = c.balanceOfToken(toObserve);

        // Assert the general rule in one expression:
        // If the call reverted, no claim. If it succeeded then:
        // 1) the decrease in c's mAsset balance equals returnedActual, i.e. before - after == returnedActual
        // 2) the observed user's balanceOfToken did not increase (credits -> underlying should not increase by redeem)
        assert(
            reverted || (
                beforeContractMAsset >= afterContractMAsset &&
                beforeContractMAsset - afterContractMAsset == returnedActual &&
                afterBalanceOfToken <= beforeBalanceOfToken
            )
        );
    }

    // allow receiving tokens/ether if needed by c calls
    receive() external payable {}
