        uint256 rateAfter = c.savings().exchangeRate();
        uint256 balAfter = c.balanceOfToken(beneficiary);

        // General rule asserted:
        // If supplyTokenTo succeeded (did not revert) then the beneficiary's balanceOfToken
        // measured after must be >= balBefore, and the increase in underlying (balAfter - balBefore)
        // must be at least the supplied mAssetAmount * min(rateBefore, rateAfter) / 1e18.
        // This captures that supplying mAsset m should not decrease beneficiary's underlying
        // and should reflect new credits converted by the prevailing exchange rate.

        // Avoid underflow in subtraction by comparing via >= and using multiplication.
        assert(
            reverted || (
                balAfter >= balBefore &&
                // compare in a safe way: (balAfter - balBefore) * 1e18 >= mAssetAmount * min(rateBefore, rateAfter)
                ( (balAfter - balBefore) * 1e18 >= mAssetAmount * (rateBefore <= rateAfter ? rateBefore : rateAfter) )
            )
        );
