        uint256 beforeContractEther = address(c).balance;
        uint256 beforeMAssetBalance = c.mAsset().balanceOf(address(c));

        // perform the state-changing call at top-level and capture revert
        bool reverted;
        uint256 returnedAmount;
        try c.redeemToken(mAssetAmount) returns (uint256 got) {
            reverted = false;
            returnedAmount = got;
        } catch {
            reverted = true;
            returnedAmount = 0;
        }

        // observe after-values via public surface
        uint256 afterContractEther = address(c).balance;
        uint256 afterMAssetBalance = c.mAsset().balanceOf(address(c));

        // General rule: if redeemToken succeeded then the contract's mAsset balance
        // decreased by at least the returnedAmount, and the contract's Ether balance didn't change.
        assert(reverted || ((beforeMAssetBalance >= afterMAssetBalance) && (beforeMAssetBalance - afterMAssetBalance >= returnedAmount) && (afterContractEther == beforeContractEther)));
    }

    receive() external payable {}
}

