contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry performing the property check
    function run(uint256 mAssetAmount, address to) public payable {
        require(to != address(0));

        // Record exchange rate and balanceOfToken(to) before supply
        uint256 rateBefore = c.savings().exchangeRate();
        uint256 beforeBal = c.balanceOfToken(to);

        // Try calling supplyTokenTo; it may revert (e.g., transferFrom failure)
        bool supplyReverted;
        try c.supplyTokenTo(mAssetAmount, to) {
            supplyReverted = false;
        } catch {
            supplyReverted = true;
        }

        // After-call observations
        uint256 rateAfter = c.savings().exchangeRate();
        uint256 afterBal = c.balanceOfToken(to);

        // The invariant: if supply succeeded then afterBal >= beforeBal + floor(mAssetAmount * rateBefore / 1e18)
        // Also, redeemToken (if called) should not increase caller's balance; we enforce that by stating
        // that imBalances are reflected via balanceOfToken and so supplies are non-negative changes.
        uint256 expectedIncrease = (mAssetAmount * rateBefore) / 1e18;

        assert(
            supplyReverted || afterBal >= beforeBal + expectedIncrease
        );
    }

    // accept Ether if needed
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry performing the property check
    function run(uint256 mAssetAmount) public payable {
        // no precondition on mAssetAmount

        // Observe contract mAsset token balance before redeem attempt via savings underlying balance on c
        // We can observe address(c).balance for Ether but mAsset is an ERC20; however C exposes mAsset via depositToken()
        // and mAsset token's balanceOf is not directly callable here; instead we rely on balanceOfToken(msg.sender)
        // and address(this).balance is available for ETH but C uses mAsset (ERC20). So we check two properties:
        // 1) If redeemToken succeeds, the caller's balanceOfToken (which returns underlying mAssets converted) does not increase.
        // 2) If redeemToken succeeds, then the call returned a nonnegative mAssetsActual and the test contract's own balance of mAsset increases by that amount.

        // Record balanceOfToken(msg.sender) before
        uint256 beforeUnderlyingBalance = c.balanceOfToken(address(this));

        // Record mAsset token address and balanceOf of this test contract by calling IERC20 via the public depositToken()
        address tokenAddr = c.depositToken();
        IERC20 token = IERC20(tokenAddr);
        uint256 beforeTokenBalance = token.balanceOf(address(this));

        // Attempt redeemToken; it may revert
        bool redeemReverted;
        uint256 returned;
        try c.redeemToken(mAssetAmount) returns (uint256 mAssetsActual) {
            redeemReverted = false;
            returned = mAssetsActual;
        } catch {
            redeemReverted = true;
            returned = 0;
        }

        // Observations after
        uint256 afterUnderlyingBalance = c.balanceOfToken(address(this));
        uint256 afterTokenBalance = token.balanceOf(address(this));

        // Assert the general rule:
        // If redeem did not revert then (a) the caller's balanceOfToken did not increase, and
        // (b) the ERC20 token balance of this contract increased by exactly the returned amount.
        assert(
            redeemReverted || (afterUnderlyingBalance <= beforeUnderlyingBalance && afterTokenBalance == beforeTokenBalance + returned)
        );
    }

    // Minimal IERC20 interface used for balanceOf observation
    interface IERC20 {
        function balanceOf(address account) external view returns (uint256);
    }

    receive() external payable {}
}
